<?php
/** PLAN=plan.json wp eval-file race.php SECONDS [READERS] [PAUSE_US]: 4 writers and 3 readers on the plugin's tables, then every row is compared with a fresh copy. Writers note their objects the way the plugin does. */
global $wpdb; $sec = (int) $args[0]; $readers = (int) ( $args[1] ?? 3 ); $argv = array( 0, $args[0], $args[1] ?? 3, $args[2] ?? 15000 ); $Q = $wpdb->prefix . 'speedup_meta_queue'; $PO = $wpdb->posts; $PM = $wpdb->postmeta;
function smt( $m ) { global $wpdb; return ( new SpeedUp_Meta_Tables_Engine( $m, $wpdb->prefix, array( 'connect' => fn() => ( new wpdb( DB_USER, DB_PASSWORD, DB_NAME, DB_HOST ) )->dbh ) ) )->load( true ); }
function con() { return ( new wpdb( DB_USER, DB_PASSWORD, DB_NAME, DB_HOST ) )->dbh; }
$P = json_decode( file_get_contents( getenv( 'PLAN' ) ), true ); $m = con(); $ids = array_column( $m->query( "select ID from $PO where post_type='product' order by ID limit 25" )->fetch_all(), 0 ); $m->close(); $kids = array(); @array_map( 'unlink', glob( '/tmp/race.*' ) );
for ( $w = 0; $w < 4 + $readers; $w++ ) { $pid = pcntl_fork(); if ( $pid ) { $kids[] = $pid; continue; }
	$m = con(); mt_srand( $w + 1 ); $end = microtime( true ) + $sec; $lat = array(); $n = 0; $st = 0;
	if ( $w < 4 ) { while ( microtime( true ) < $end ) { $id = $ids[ mt_rand( 0, 24 ) ]; foreach ( array( array( '_stock', mt_rand( -50, 99 ) ), array( '_supplier', 'SUP-' . str_pad( (string) mt_rand( 1, 60 ), 3, '0', STR_PAD_LEFT ) ), array( '_purchase_cost', mt_rand( 1, 99 ) . '.5' ) ) as $x ) { $t = hrtime( true ); $m->query( "UPDATE $PM SET meta_value='{$x[1]}' WHERE post_id=$id AND meta_key='{$x[0]}'" ); $lat[] = ( hrtime( true ) - $t ) / 1e6; } if ( ! $m->query( "INSERT INTO $Q VALUES('post',$id,1) ON DUPLICATE KEY UPDATE seq=seq+1" ) ) { file_put_contents( "/tmp/race.err$w", $m->error . "\n", FILE_APPEND ); } $n++; usleep( (int) ( $argv[3] ?? 15000 ) ); } }
	else { while ( microtime( true ) < $end ) { try { $h = smt( $m ); foreach ( array( 'P1', 'P5', 'P8' ) as $k ) { $r = $h->handle( $P[ $k ][0] ); if ( null === $r ) { $st++; } $m->query( $r ?? $P[ $k ][0] ); $n++; $h->found = null; } $h->close(); } catch ( Throwable $e ) { file_put_contents( "/tmp/race.err$w", $e->getMessage() . "\n", FILE_APPEND ); @$m->rollback(); } } }
	sort( $lat ); file_put_contents( "/tmp/race.$w", json_encode( array( $n, $st, $lat ? $lat[ intdiv( count( $lat ), 2 ) ] : 0, $lat ? $lat[ (int) ( count( $lat ) * .99 ) ] : 0 ) ) ); posix_kill( getmypid(), 9 ); }
foreach ( $kids as $k ) { pcntl_waitpid( $k, $s ); }
$W = 0; $R = 0; $S = 0; $med = array(); $p99 = array(); for ( $w = 0; $w < 4 + $readers; $w++ ) { $x = json_decode( file_get_contents( "/tmp/race.$w" ), true ); if ( $w < 4 ) { $W += $x[0]; $med[] = $x[2]; $p99[] = $x[3]; } else { $R += $x[0]; $S += $x[1]; } }
$m = con(); if ( $readers ) { $h = smt( $m ); $h2 = smt( $m ); $h2->drain( 'post' ); $bad = 0; $left = $m->query( "select count(*) from $Q" )->fetch_row()[0];
foreach ( $h2->reg as $d ) { if ( 'post' !== $d['ent'] || ! in_array( 'product', $d['types'], true ) ) { continue; } $l = implode( ',', $ids ); $cols = "object_id,"; foreach ( $d['keys'] as $k ) { if ( $k['row'] ) { foreach ( $k['casts'] as $c ) { $cols .= "$c,"; } } } $cols = rtrim( $cols, ',' ); $a = $m->query( "SELECT $cols FROM {$d['table']} WHERE object_id IN ($l) ORDER BY 1" )->fetch_all(); $h2->refresh( 'post', $ids ); $b = $m->query( "SELECT $cols FROM {$d['table']} WHERE object_id IN ($l) ORDER BY 1" )->fetch_all(); foreach ( $a as $i => $r ) { if ( $r !== $b[ $i ] ) { $bad++; } }
	$cn = $m->query( "SELECT SUM(cnt) FROM {$h2->pre}counts WHERE tab='{$d['table']}' GROUP BY k" )->fetch_all(); $tot = $m->query( "SELECT COUNT(*) FROM {$d['table']}" )->fetch_row()[0]; foreach ( $cn as $x ) { if ( $x[0] !== $tot ) { $bad++; } } $x = $d['keys']['_supplier'] ?? null; if ( $x ) { $c = $x['casts']['']; $u = $m->query( "SELECT COUNT(*) FROM (SELECT $c v,COUNT(*) n FROM {$d['table']} WHERE $c IS NOT NULL GROUP BY $c) t LEFT JOIN (SELECT val,SUM(cnt) n FROM {$h2->pre}counts WHERE tab='{$d['table']}' AND k={$x['n']} AND miss=0 GROUP BY val) c ON c.val=t.v WHERE c.n IS NULL OR c.n<>t.n" )->fetch_row()[0]; $bad += (int) $u; echo "supplier counters wrong: $u\n"; } } }
printf( "%d s: %d write rounds, %d reads (%d sent to meta table), write median %.2f ms p99 %.2f ms, left in queue %s, stale rows or counters %s\n", $sec, $W, $R, $S, array_sum( $med ) / 4, max( $p99 ), $left ?? '-', $bad ?? '-' ); foreach ( glob( '/tmp/race.err*' ) as $f ) { $x = array_count_values( file( $f ) ); arsort( $x ); foreach ( array_slice( $x, 0, 2 ) as $k => $v ) { echo "ERR $v x $k"; } }
